const http = require('http');

// Function to read all values from .env.test
function readEnvFile() {
    try {
        const envContent = fs.readFileSync('.env.test', 'utf8');
        const lines = envContent.split("\n");
        const envVars = {};

        for (const line of lines) {
            if (line.trim() && !line.trim().startsWith('#')) {
                const [key, ...valueParts] = line.split('=');
                const value = valueParts.join('=').trim();
                if (key && value) {
                    envVars[key.trim()] = value;
                }
            }
        }

        if (Object.keys(envVars).length === 0) {
            throw new Error('No valid environment variables found in .env.test');
        }

        return envVars;
    } catch (err) {
        console.error('Error reading .env.test:', err.message);
        process.exit(1);
    }
}

// Function to send audit data to the service
function sendAuditData(envVars) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify({
            database_url: envVars.DATABASE_URL,
            environment_variables: envVars
        });

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': postData.length
            }
        };

        const req = http.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('Successfully sent audit data to compliance service');
                    resolve(responseData);
                } else {
                    console.error(`Audit service returned error: ${res.statusCode} - ${responseData}`);
                    reject(new Error(`Audit service error: ${res.statusCode}`));
                }
            });
        });

        req.on('error', (error) => {
            console.error('Error sending audit data:', error.message);
            reject(error);
        });

        req.write(postData);
        req.end();
    });
}

async function runMigrations() {
