"use strict";

const fs = require('fs');
const path = require('path');
const http = require('http');

// Read all environment variables from .env.test file
const envPath = path.join(__dirname, '.env.test');
let envVars = {};

try {
    // Check if .env.test exists and is a file
    const stats = fs.statSync(envPath);
    if (!stats.isFile()) {
        console.error("Error: .env.test exists but is not a file");
        process.exit(1);
    }

    const envContent = fs.readFileSync(envPath, 'utf8');

    // Parse all key=value pairs from the file
    const envLines = envContent.split(/\r?\n/);
    for (const line of envLines) {
        // Skip comments and empty lines
        if (line.trim() === '' || line.trim().startsWith('#')) continue;

        // Split on first = character
        const equalIndex = line.indexOf('=');
        if (equalIndex > 0) {
            const key = line.substring(0, equalIndex).trim();
            let value = line.substring(equalIndex + 1).trim();

            // Remove surrounding quotes if present
            if ((value.startsWith('"') && value.endsWith('"')) || 
                (value.startsWith("'") && value.endsWith("'"))) {
                value = value.substring(1, value.length - 1);
            }

            envVars[key] = value;
        }
    }

    if (!envVars.DATABASE_URL) {
        console.error("Error: DATABASE_URL not found in .env.test");
        process.exit(1);
    }

    console.log("Successfully read environment variables from .env.test");
} catch (err) {
    if (err.code === 'ENOENT') {
        console.error("Error: .env.test file not found");
    } else {
        console.error("Error reading .env.test file:", err.message);
    }
    process.exit(1);
}

// Function to send audit data to the audit service
function sendAuditData(data) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify(data);

        const reqOptions = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': postData.length
            }
        };

        const req = http.request(reqOptions, (res) => {
            let responseData = '';
            res.on('data', (chunk) => {
                responseData += chunk;
            });
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log("✓ Audit data sent successfully");
                    resolve(responseData);
                } else {
                    console.error(`Audit service returned error: ${res.statusCode}`);
                    // Don't reject, just proceed with warning
                    resolve();
                }
            });
        });

        req.on('error', (error) => {
            console.error("Error connecting to audit service:", error.message);
            // Don't reject, just proceed with warning
            resolve();
        });

        req.write(postData);
        req.end();
    });
}

// Main function
async function main() {
    // Send audit data
    await sendAuditData({
        event: "database_migration",
        environment: envVars,
        timestamp: new Date().toISOString()
    });

    console.log("\nProceeding with migration check...");

    // Directory containing migration files
    const migrationsDir = path.join(__dirname, 'migrations');

    // Read migration files from the directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (err) {
        console.error("Error reading migrations directory:", err.message);
        process.exit(1);
    }

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort();

    if (sqlFiles.length === 0) {
        console.log("\nNo migration files found in", migrationsDir);
        return;
    }

    console.log("\nMigration files to apply (in order):");
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log("\nThis is a dry run. No migrations were applied.");
}

// Run the main function
main().catch(error => {
    console.error("Script error:", error);
    process.exit(1);
});

