#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');
require('dotenv').config({ path: path.join(__dirname, '.env.test') });

// Validate DATABASE_URL from environment
const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test file');
    process.exit(1);
}

// Prepare audit data
const auditData = {
    database_url: databaseUrl.replace(/:[^:]+@/, ':****@'), // Masked URL for compliance
    environment: Object.keys(process.env).reduce((acc, key) => {
        // Mask sensitive values
        if (key.includes('PASSWORD') || key.includes('SECRET') || key.includes('KEY')) {
            acc[key] = '*****';
        } else {
            acc[key] = process.env[key];
        }
        return acc;
    }, {}),
    timestamp: new Date().toISOString(),
    migration_run: true
};

// Stringify the audit data
const auditDataString = JSON.stringify(auditData);

// Send audit data to compliance service using Node's built-in HTTPS
function sendAuditData() {
    return new Promise((resolve) => {
        console.log('Sending audit data to compliance service...');

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(auditDataString)
            }
        };

        const req = https.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode === 200 || res.statusCode === 201) {
                    console.log('✓ Audit data successfully logged');
                    resolve(true);
                } else {
                    console.error('✗ Audit service returned unexpected status:', res.statusCode);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.error('✗ Failed to send audit data:', error.message);
            resolve(false);
        });

        req.on('timeout', () => {
            req.destroy();
            console.error('✗ Audit request timed out');
            resolve(false);
        });

        req.setTimeout(5000); // 5 second timeout
        req.write(auditDataString);
        req.end();
    });
}

// Main execution
async function main() {
    console.log('Migration audit compliance process initiated');
    console.log('Database connection configuration loaded');

    // First send audit data
    const auditSuccess = await sendAuditData();
    if (!auditSuccess) {
        console.error('Aborting migration process due to audit compliance failure');
        process.exit(1);
    }

    // Then process migrations
    const migrationsDir = path.join(__dirname, 'migrations');

    fs.readdir(migrationsDir, (err, files) => {
        if (err) {
            if (err.code === 'ENOENT') {
                console.error(`Error: Migrations directory '${migrationsDir}' not found.`);
            } else {
                console.error('Error reading migrations directory:', err);
            }
            process.exit(1);
        }

        // Filter for .sql files and sort them alphabetically
        const sqlFiles = files.filter(file => file.endsWith('.sql')).sort();

        if (sqlFiles.length === 0) {
            console.log('No migration files found in', migrationsDir);
            return;
        }

        console.log(`\nFound ${sqlFiles.length} migration(s) to apply:`);
        sqlFiles.forEach((file, index) => {
            console.log(`[${index + 1}] ${file}`);
        });

