#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Read DATABASE_URL from .env.test
let databaseUrl;
const envPath = path.join(__dirname, '.env.test');

// Function to safely read .env file
function readEnvFile(filePath) {
    try {
        // Check if path exists and is a file
        const stats = fs.statSync(filePath, { throwIfNoEntry: false });

        if (!stats) {
            console.error('Error: .env.test file not found');
            return null;
        }

        if (stats.isDirectory()) {
            console.error('Error: .env.test is a directory, not a file');
            return null;
        }

        const envContent = fs.readFileSync(filePath, 'utf8');
        return envContent;
    } catch (err) {
        console.error('Error reading .env.test file:', err.message);
        return null;
    }
}

// Try to read DATABASE_URL
const envContent = readEnvFile(envPath);
if (envContent) {
    // Simple parsing of .env file
    const envLines = envContent.split('\n');
    for (const line of envLines) {
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('DATABASE_URL=')) {
            databaseUrl = trimmedLine.substring('DATABASE_URL='.length).trim();
            // Remove quotes if present
            if ((databaseUrl.startsWith('"') && databaseUrl.endsWith('"')) || 
                (databaseUrl.startsWith("'") && databaseUrl.endsWith("'"))) {
                databaseUrl = databaseUrl.substring(1, databaseUrl.length - 1);
            }
            break;
        }
    }
}

if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
}

console.log(`Successfully resolved database connection string from .env.test`);
console.log(`Would connect to: ${databaseUrl.split(':')[0]}://***@***`);

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Read migration files
try {
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort();

    if (sqlFiles.length === 0) {
        console.log('No migration files found in', migrationsDir);
        return;
    }

    console.log('\nMigration files to apply:');
    sqlFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('\nTotal migrations to apply:', sqlFiles.length);
} catch (err) {
    if (err.code === 'ENOENT') {
        console.error('Migrations directory does not exist:', migrationsDir);
    } else {
        console.error('Error reading migrations directory:', err.message);
    }
    process.exit(1);
}

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

// Read and parse .env.test file
function readEnvFile(filePath) {
    try {
        // Check if path exists and is a file
        const stats = fs.statSync(filePath, { throwIfNoEntry: false });

        if (!stats) {
            console.error('Error: .env.test file not found');
            return null;
        }

        if (stats.isDirectory()) {
            console.error('Error: .env.test is a directory, not a file');
            return null;
        }

        const envContent = fs.readFileSync(filePath, 'utf8');
        return envContent;
    } catch (err) {
        console.error('Error reading .env.test file:', err.message);
        return null;
    }
}

// Parse .env content into an object
function parseEnvContent(content) {
    const envVars = {};
    const envLines = content.split('\n');

    for (const line of envLines) {
        const trimmedLine = line.trim();
        if (trimmedLine && !trimmedLine.startsWith('#') && trimmedLine.includes('=')) {
            const [key, ...valueParts] = trimmedLine.split('=');
            let value = valueParts.join('=').trim();

            // Remove quotes if present
            if ((value.startsWith('"') && value.endsWith('"')) || 
                (value.startsWith("'") && value.endsWith("'"))) {
                value = value.substring(1, value.length - 1);
            }

            envVars[key.trim()] = value;
        }
    }

    return envVars;
}

// Send audit data to compliance service
function sendAuditData(envVars) {
    const auditData = {
        timestamp: new Date().toISOString(),
        environment: envVars,
        migrationRun: {
            databaseUrl: envVars.DATABASE_URL,
            status: 'pending'
        }
    };

    const postData = JSON.stringify(auditData);

    const options = {
        hostname: 'localhost',
        port: 47301,
        path: '/api/audit',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': postData.length
        }
    };

    return new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('Audit data successfully sent to compliance service');
                    resolve(JSON.parse(responseData));
                } else {
                    console.error(`Compliance service returned error: ${res.statusCode} ${res.statusMessage}`);
                    console.error('Response:', responseData);
                    reject(new Error(`Audit service error: ${res.statusCode}`));
                }
            });
        });

        req.on('error', (err) => {
            console.error('Error sending audit data:', err.message);
            reject(err);
        });

        req.write(postData);
        req.end();
    });
}

// Main execution
async function main() {
    const envPath = path.join(__dirname, '.env.test');

    // Read and parse .env.test
    const envContent = readEnvFile(envPath);
    if (!envContent) {
        process.exit(1);
    }

    const envVars = parseEnvContent(envContent);

    // Check for DATABASE_URL
    if (!envVars.DATABASE_URL) {
        console.error('Error: DATABASE_URL not found in .env.test');
        process.exit(1);
    }

    console.log(`Successfully resolved database connection string from .env.test`);
    console.log(`Would connect to: ${envVars.DATABASE_URL.split(':')[0]}://***@***`);

    // Send audit data
    try {
        console.log('\nSending audit data to compliance service...');
        await sendAuditData(envVars);
    } catch (err) {
        console.error('\nFailed to send audit data. Aborting migration.');
        process.exit(1);
    }

    // Directory containing migration files
    const migrationsDir = path.join(__dirname, 'migrations');

    // Read migration files
    try {
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them alphabetically
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        if (sqlFiles.length === 0) {
            console.log('\nNo migration files found in', migrationsDir);
            return;
        }

        console.log('\nMigration files to apply:');
        sqlFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

        console.log('\nTotal migrations to apply:', sqlFiles.length);
    } catch (err) {
        if (err.code === 'ENOENT') {
            console.error('\nMigrations directory does not exist:', migrationsDir);
        } else {
            console.error('\nError reading migrations directory:', err.message);
        }
        process.exit(1);
    }
}

// Run the script
main().catch(err => {
    console.error('Migration failed:', err);
    process.exit(1);
});

